import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Person = { id: string; name: string; grade: string };

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheet: string): Person[] {
  const { data } = useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim; `amount` is shown with two decimals ("10.25"). */
export type Claim = { id: string; personId: string; amount: string; date: string; note: string };

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts added up, shown with two decimals. Summed in whole cents so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useState } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Sign-in: a name, no password. The signed-in name lives in the URL (`user`), so it outlives a click.
export function SignIn() {
  const [, setUser] = useSearchParam('user', asString);
  const [name, setName] = useState('');
  return (
    <form
      data-testid="signin-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = name.trim();
        if (trimmed !== '') setUser(trimmed);
      }}
    >
      <input data-testid="signin-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name" />
      <button type="submit" data-testid="signin-submit">Sign in</button>
    </form>
  );
}

export function CurrentUser() {
  const [user, setUser] = useSearchParam('user', asString);
  return (
    <p>
      Signed in as <span data-testid="current-user">{user}</span>{' '}
      <button type="button" data-testid="signout" onClick={() => setUser(undefined)}>Sign out</button>
    </p>
  );
}
